pub type ReadOnlyWorkspace = IsolatedWorkspace;

pub struct SnapshotWorkspace {
    inner: FsWorkspace,
    _origin: Arc<dyn Workspace>,
}

impl SnapshotWorkspace {
    pub async fn create(source_root: &Path) -> Result<Self, WorkspaceError> {
        let temp_root = std::env::temp_dir().join(format!("harness-snapshot-{}", uuid::Uuid::new_v4()));
        copy_dir_recursive(source_root, &temp_root).await?;
        Ok(Self {
            inner: FsWorkspace::new(temp_root),
            _origin: Arc::new(FsWorkspace::new(source_root.to_path_buf())),
        })
    }
}

#[async_trait::async_trait]
impl Workspace for SnapshotWorkspace {
    fn root(&self) -> &Path {
        self.inner.root()
    }
    fn mode(&self) -> WorkspaceMode {
        WorkspaceMode::Isolated
    }
    async fn read(&self, p: &str) -> Result<String, WorkspaceError> {
        self.inner.read(p).await
    }
    async fn write(&self, p: &str, c: &str) -> Result<(), WorkspaceError> {
        self.inner.write(p, c).await
    }
    async fn search(&self, q: &str) -> Result<SearchResult, WorkspaceError> {
        self.inner.search(q).await
    }
    async fn list_files(&self, d: usize) -> Result<Vec<FileInfo>, WorkspaceError> {
        self.inner.list_files(d).await
    }
}
