    /// Creates an `AgentCapabilities` with two tools:
    /// - `fs.read`    (delegatable, enabled)
    /// - `shell.exec` (not delegatable, enabled)
    fn parent_with_mixed_tools() -> (AgentCapabilities, ToolId, ToolId) {
