//! Durable mutable state owned by an agent.

use std::collections::HashMap;

use harness_protocol::commands::{AgentError, AgentOperation, AgentStatus};
use harness_protocol::ids::{AgentId, PermissionId, RunId, Timestamp, ToolCallId};
use harness_protocol::messages::AgentMessage;
use harness_protocol::tools::ToolCall;

#[derive(Debug, Clone)]
pub struct PendingToolCall {
    pub call: ToolCall,
    pub started_at: Timestamp,
}

#[derive(Debug, Clone)]
pub struct AgentState {
    pub status: AgentStatus,
    pub current_operation: Option<AgentOperation>,
    pub system_prompt: String,
    pub messages: Vec<AgentMessage>,
    pub active_run: Option<RunId>,
    pub pending_tools: HashMap<ToolCallId, PendingToolCall>,
    /// Exact correlation from a permission request to its pending tool call.
    pub pending_permissions: HashMap<PermissionId, ToolCallId>,
    pub children: Vec<AgentId>,
    pub last_error: Option<AgentError>,
    /// Monotonic source for IDs and timestamps created by deterministic transitions.
    pub transition_sequence: u64,
}

//! Agent domain entity. All external work is represented as effects from `Agent::apply`.

use harness_protocol::backend::BackendBinding;
use harness_protocol::commands::AgentStatus;
use harness_protocol::ids::{AgentId, SessionId};
use harness_protocol::usage::AgentBudget;

use crate::agent_state::AgentState;
use crate::capabilities::AgentCapabilities;

#[derive(Debug, Clone, Default)]
pub struct UsageLedger {
    pub records: Vec<harness_protocol::usage::UsageRecord>,
}

#[derive(Debug, Clone)]
pub struct Agent {
    pub id: AgentId,
    pub session_id: SessionId,
    pub parent_id: Option<AgentId>,
    pub state: AgentState,
    pub backend: BackendBinding,
    pub capabilities: AgentCapabilities,
    pub usage: UsageLedger,
    pub budget: AgentBudget,
}

impl Agent {
    pub fn new(
        id: AgentId,
        session_id: SessionId,
        parent_id: Option<AgentId>,
        system_prompt: String,
        backend: BackendBinding,
        capabilities: AgentCapabilities,
        budget: AgentBudget,
    ) -> Self {
        Self {
            id,
            session_id,
            parent_id,
            state: AgentState {
                status: AgentStatus::Idle,
                current_operation: None,
                system_prompt,
                messages: Vec::new(),
                active_run: None,
                pending_tools: Default::default(),
                pending_permissions: Default::default(),
                children: Vec::new(),
                last_error: None,
                transition_sequence: 0,
            },
            backend,
            capabilities,
            usage: UsageLedger::default(),
            budget,
        }
    }

    pub fn is_root(&self) -> bool {
        self.parent_id.is_none()
    }
}

