    use super::*;

    struct NoopSink;
    impl EventSink for NoopSink {
        fn send(&self, _envelope: AgentEventEnvelope) {}
    }

    /// A test event sink that records every envelope so tests can observe the
    /// events streamed by a child's resolved backend.
    #[derive(Default)]
    struct RecordingSink {
        events: Mutex<Vec<AgentEventEnvelope>>,
    }
    impl EventSink for RecordingSink {
        fn send(&self, envelope: AgentEventEnvelope) {
            self.events.lock().unwrap().push(envelope);
        }
    }

    /// A test integration factory that returns a fresh [`FakeBackend`] with the
    /// scripted behavior configured at construction.
    struct FakeIntegrationFactory {
        id: &'static str,
        backend: FakeBackend,
    }

    #[async_trait]
    impl IntegrationFactory for FakeIntegrationFactory {
        fn id(&self) -> &'static str {
            self.id
        }

        fn descriptor(&self) -> BackendDescriptor {
            self.backend.descriptor()
        }

        async fn create(
            &self,
            _config: Value,
        ) -> Result<Arc<dyn ExecutionBackend>, Box<dyn std::error::Error + Send + Sync>> {
            Ok(Arc::new(self.backend.clone()))
        }
    }

    /// Stable integration identifier (as a UUID string) under which the
    /// explicit-child factory is registered in the integration registry.
    const CHILD_FAKE_INTEGRATION: &str = "00000000-0000-0000-0000-00000000c0de";

    /// A scripted execution result used to complete the child run cleanly.
    fn scripted_result() -> ExecutionResult {
        ExecutionResult {
            request_id: RequestId::new(),
            usage: Default::default(),
            cost: Default::default(),
            finish_reason: "end_turn".into(),
        }
    }

    /// Polls `sink` (with timeout) for an `AssistantTextDelta` equal to `expected`.
    async fn sink_received_text_delta(sink: &RecordingSink, expected: &str) -> bool {
        let deadline = tokio::time::Instant::now() + Duration::from_secs(2);
        loop {
            {
                let events = sink.events.lock().unwrap();
                if events.iter().any(|env| {
                    matches!(
                        &env.event,
                        AgentEvent::AssistantTextDelta { delta, .. } if delta == expected
                    )
                }) {
                    return true;
                }
            }
            if tokio::time::Instant::now() >= deadline {
                return false;
            }
            tokio::time::sleep(Duration::from_millis(5)).await;
        }
    }

    #[tokio::test]
    async fn max_children_gate_rejects_third_child() {
        let supervisor = AgentSupervisor::new(SessionId::new(), SessionCancellation::new());
        let parent_id = AgentId::new();
        let budget = AgentBudget {
            max_children: Some(2),
            ..Default::default()
        };

        // Register two fake children under the parent (no real task spawned).
        for _ in 0..2 {
            let child_id = AgentId::new();
            let cancel = supervisor.session_cancel.child_token();
            let join = tokio::spawn(async {});
            supervisor
                .register(Some(parent_id), child_id, 1, cancel, join)
                .await;
        }

        // A third child must be rejected before any task is created.
        let result = supervisor
            .max_children_depth_check(parent_id, 0, &budget)
            .await;
        assert!(matches!(
            result,
            Err(SupervisorError::Budget(BudgetError::TooManyChildren { .. }))
        ));
    }

    /// Integration test (spec §21 / Task 6.2): spawning a child with
    /// `ToolInheritance::Subset([fs.read])` from a parent that also holds a
    /// non-delegatable `shell.exec` yields a child whose capability set
    /// contains exactly `[fs.read]` (non-escalation invariant).
    #[tokio::test]
    async fn spawn_child_inherits_only_delegatable_tools() {
        let session_id = SessionId::new();
        let supervisor = AgentSupervisor::new(session_id, SessionCancellation::new());

        // Parent toolset: fs.read (delegatable) + shell.exec (not delegatable).
        let fs_read_id = harness_protocol::ids::ToolId::new();
        let shell_exec_id = harness_protocol::ids::ToolId::new();
        let mut tools = HashMap::new();
        tools.insert(
            fs_read_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: fs_read_id,
                    name: "fs.read".into(),
                    description: "Read files".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: true,
            },
        );
        tools.insert(
            shell_exec_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: shell_exec_id,
                    name: "shell.exec".into(),
                    description: "Execute shell commands".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: false,
            },
        );

        let parent = Agent::new(
            AgentId::new(),
            session_id,
            None,
            "system".into(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: "fake".into(),
                    description: "fake".into(),
                    capabilities: BackendCapabilities::default(),
                },
            },
            AgentCapabilities {
                tools: AgentToolset { tools },
                can_spawn_agents: true,
                max_child_depth: Some(5),
                workspace: WorkspaceCapabilities {
                    can_read: true,
                    can_write: false,
                    can_search: false,
                },
                backend: BackendCapabilities::default(),
            },
            AgentBudget::default(),
        );

        let parent_backend: Arc<dyn ExecutionBackend> = Arc::new(FakeBackend::new());
        let tool_registry: Arc<dyn ToolRegistry> = Arc::new(FakeToolRegistry::new());
        let workspace: Arc<dyn Workspace> = Arc::new(FakeWorkspace::new());
        let event_sink: Arc<dyn EventSink> = Arc::new(NoopSink);
        let scheduler: Arc<Scheduler> = Arc::new(Scheduler::new(SchedulerConfig::default()));
        let integration_registry = IntegrationRegistry::new();

        let spec = SpawnAgentSpec {
            role: Some("child".into()),
            backend: BackendPolicy::Inherit,
            tools: ToolInheritance::Subset(vec![fs_read_id]),
            workspace: WorkspacePolicy::Inherit,
            budget: AgentBudget::default(),
            mode: SpawnMode::Concurrent,
        };

        let child_id = supervisor
            .spawn_child(
                &parent,
                parent_backend,
                &integration_registry,
                tool_registry,
                workspace,
                event_sink,
                scheduler,
                spec,
            )
            .await
            .expect("spawn child should succeed");

        let child_caps = supervisor
            .child_capabilities(child_id)
            .await
            .expect("child capabilities should be retained by the supervisor");

        // The child must inherit exactly the delegatable fs.read tool and
        // must NOT inherit the non-delegatable shell.exec tool.
        assert_eq!(
            child_caps.tools.tools.len(),
            1,
            "child must inherit exactly one tool (fs.read), got {:?}",
            child_caps.tools.tools.keys().collect::<Vec<_>>()
        );
        assert!(
            child_caps.tools.tools.contains_key(&fs_read_id),
            "fs.read must be inherited by the child"
        );
        assert!(
            !child_caps.tools.tools.contains_key(&shell_exec_id),
            "shell.exec must not be inherited by the child"
        );
    }

    /// Acceptance test (Task 6.6): spawning a child with
    /// `BackendPolicy::Explicit` referencing a second registered
    /// [`FakeBackend`] (via [`FakeIntegrationFactory`]) must give the child its
    /// **own** backend instance. The child must execute against that backend's
    /// scripted events — never against the parent's.
    #[tokio::test]
    async fn explicit_backend_resolves_to_registered_integration_not_parent() {
        let session_id = SessionId::new();
        let supervisor = AgentSupervisor::new(session_id, SessionCancellation::new());

        // Parent backend streams a distinctive marker the child must NOT use.
        let parent_backend: Arc<dyn ExecutionBackend> = Arc::new(
            FakeBackend::new()
                .with_events(vec![ExecutionEvent::TextDelta {
                    request_id: RequestId::new(),
                    delta: "parent-backend".into(),
                }])
                .with_result(scripted_result()),
        );

        // The second (explicitly referenced) backend streams a different marker.
        let child_marker = "explicit-child-backend";
        let child_backend = FakeBackend::new()
            .with_events(vec![ExecutionEvent::TextDelta {
                request_id: RequestId::new(),
                delta: child_marker.into(),
            }])
            .with_result(scripted_result());

        let integration_registry = IntegrationRegistry::new();
        integration_registry
            .register(Arc::new(FakeIntegrationFactory {
                id: CHILD_FAKE_INTEGRATION,
                backend: child_backend,
            }))
            .expect("register explicit-child factory");

        let parent = Agent::new(
            AgentId::new(),
            session_id,
            None,
            "system".into(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: "parent-fake".into(),
                    description: "parent backend".into(),
                    capabilities: BackendCapabilities::default(),
                },
            },
            AgentCapabilities {
                tools: AgentToolset {
                    tools: HashMap::new(),
                },
                can_spawn_agents: true,
                max_child_depth: Some(5),
                workspace: WorkspaceCapabilities {
                    can_read: true,
                    can_write: false,
                    can_search: false,
                },
                backend: BackendCapabilities::default(),
            },
            AgentBudget::default(),
        );

        let tool_registry: Arc<dyn ToolRegistry> = Arc::new(FakeToolRegistry::new());
        let workspace: Arc<dyn Workspace> = Arc::new(FakeWorkspace::new());
        let recording = Arc::new(RecordingSink::default());
        let event_sink: Arc<dyn EventSink> = recording.clone();
        let scheduler: Arc<Scheduler> = Arc::new(Scheduler::new(SchedulerConfig::default()));

        // Explicitly reference the integration registered above (by its stable
        // string id, the same key the registry keys factories under).
        let child_reference = BackendReference {
            integration: CHILD_FAKE_INTEGRATION.parse().unwrap(),
            configuration: ConfigurationId::new(),
            model: None,
        };

        let spec = SpawnAgentSpec {
            role: Some("child".into()),
            backend: BackendPolicy::Explicit(child_reference),
            tools: ToolInheritance::InheritAll,
            workspace: WorkspacePolicy::Inherit,
            budget: AgentBudget::default(),
            mode: SpawnMode::Concurrent,
        };

        let child_id = supervisor
            .spawn_child(
                &parent,
                parent_backend,
                &integration_registry,
                tool_registry,
                workspace,
                event_sink,
                scheduler,
                spec,
            )
            .await
            .expect("spawn child should succeed");

        // Drive the child: it must execute against the explicitly referenced
        // backend (the factory's scripted events), never the parent's.
        let commands = supervisor
            .child_commands(child_id)
            .await
            .expect("child command sender should be retained by the supervisor");
        commands
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "run".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun to child");

        assert!(
            sink_received_text_delta(&recording, child_marker).await,
            "child should stream events from the explicitly referenced backend"
        );

        // The parent backend's distinctive marker must never surface.
        let events = recording.events.lock().unwrap();
        assert!(
            !events.iter().any(|env| {
                matches!(
                    &env.event,
                    AgentEvent::AssistantTextDelta { delta, .. } if delta == "parent-backend"
                )
            }),
            "child must NOT execute against the parent backend"
        );
    }
}

