    /// Builds a spawnable parent agent holding one delegatable `fs.read` tool.
    fn parent_agent(session_id: SessionId) -> (Agent, ToolId) {
        let fs_read_id = ToolId::new();
        let mut tools = HashMap::new();
        tools.insert(
            fs_read_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: fs_read_id,
                    name: "fs.read".into(),
                    description: "Read files".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: true,
            },
        );

        let parent = Agent::new(
            AgentId::new(),
            session_id,
            None,
            "system".into(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: "fake".into(),
                    description: "fake".into(),
                    capabilities: BackendCapabilities::default(),
                },
            },
            AgentCapabilities {
                tools: AgentToolset { tools },
                can_spawn_agents: true,
                max_child_depth: Some(5),
                workspace: WorkspaceCapabilities {
                    can_read: true,
                    can_write: false,
                    can_search: false,
                },
                backend: BackendCapabilities::default(),
            },
            AgentBudget::default(),
        );

        (parent, fs_read_id)
    }

    /// Exercises the full `spawn_child` path for a given workspace policy and
    /// returns the spawned child's id.
    async fn spawn_child_with_policy(
        supervisor: &AgentSupervisor,
        parent: &Agent,
        fs_read_id: ToolId,
        workspace: Arc<dyn Workspace>,
        policy: WorkspacePolicy,
    ) -> AgentId {
        let parent_backend: Arc<dyn ExecutionBackend> = Arc::new(FakeBackend::new());
        let tool_registry: Arc<dyn ToolRegistry> = Arc::new(FakeToolRegistry::new());
        let event_sink: Arc<dyn EventSink> = Arc::new(NoopSink);
        let scheduler: Arc<Scheduler> = Arc::new(Scheduler::new(SchedulerConfig::default()));
        let integration_registry = IntegrationRegistry::new();

        let spec = SpawnAgentSpec {
            role: Some("child".into()),
            backend: BackendPolicy::Inherit,
            tools: ToolInheritance::Subset(vec![fs_read_id]),
            workspace: policy,
            budget: AgentBudget::default(),
            mode: SpawnMode::Concurrent,
        };

        supervisor
            .spawn_child(
                parent,
                parent_backend,
                &integration_registry,
                tool_registry,
                workspace,
                event_sink,
                scheduler,
                spec,
            )
            .await
            .expect("spawn child should succeed")
    }

    #[tokio::test]
    async fn max_children_gate_rejects_third_child() {
        let supervisor = AgentSupervisor::new(SessionId::new(), SessionCancellation::new());
        let parent_id = AgentId::new();
        let budget = AgentBudget {
            max_children: Some(2),
            ..Default::default()
        };

        // Register two fake children under the parent (no real task spawned).
        for _ in 0..2 {
            let child_id = AgentId::new();
            let cancel = supervisor.session_cancel.child_token();
            let join = tokio::spawn(async {});
            supervisor
                .register(Some(parent_id), child_id, 1, cancel, join)
                .await;
        }

        // A third child must be rejected before any task is created.
        let result = supervisor
            .max_children_depth_check(parent_id, 0, &budget)
            .await;
        assert!(matches!(
            result,
            Err(SupervisorError::Budget(BudgetError::TooManyChildren { .. }))
        ));
    }

    /// Integration test (spec §21 / Task 6.2): spawning a child with
    /// `ToolInheritance::Subset([fs.read])` from a parent that also holds a
    /// non-delegatable `shell.exec` yields a child whose capability set
    /// contains exactly `[fs.read]` (non-escalation invariant).
    #[tokio::test]
    async fn spawn_child_inherits_only_delegatable_tools() {
        let session_id = SessionId::new();
        let supervisor = AgentSupervisor::new(session_id, SessionCancellation::new());

        // Parent toolset: fs.read (delegatable) + shell.exec (not delegatable).
        let fs_read_id = harness_protocol::ids::ToolId::new();
        let shell_exec_id = harness_protocol::ids::ToolId::new();
        let mut tools = HashMap::new();
        tools.insert(
            fs_read_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: fs_read_id,
                    name: "fs.read".into(),
                    description: "Read files".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: true,
            },
        );
        tools.insert(
            shell_exec_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: shell_exec_id,
                    name: "shell.exec".into(),
                    description: "Execute shell commands".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: false,
            },
        );

        let parent = Agent::new(
            AgentId::new(),
            session_id,
            None,
            "system".into(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: "fake".into(),
                    description: "fake".into(),
                    capabilities: BackendCapabilities::default(),
                },
            },
            AgentCapabilities {
                tools: AgentToolset { tools },
                can_spawn_agents: true,
                max_child_depth: Some(5),
                workspace: WorkspaceCapabilities {
                    can_read: true,
                    can_write: false,
                    can_search: false,
                },
                backend: BackendCapabilities::default(),
            },
            AgentBudget::default(),
        );

        let parent_backend: Arc<dyn ExecutionBackend> = Arc::new(FakeBackend::new());
        let tool_registry: Arc<dyn ToolRegistry> = Arc::new(FakeToolRegistry::new());
        let workspace: Arc<dyn Workspace> = Arc::new(FakeWorkspace::new());
        let event_sink: Arc<dyn EventSink> = Arc::new(NoopSink);
        let scheduler: Arc<Scheduler> = Arc::new(Scheduler::new(SchedulerConfig::default()));
        let integration_registry = IntegrationRegistry::new();

        let spec = SpawnAgentSpec {
            role: Some("child".into()),
            backend: BackendPolicy::Inherit,
            tools: ToolInheritance::Subset(vec![fs_read_id]),
            workspace: WorkspacePolicy::Inherit,
            budget: AgentBudget::default(),
            mode: SpawnMode::Concurrent,
        };

        let child_id = supervisor
            .spawn_child(
                &parent,
                parent_backend,
                &integration_registry,
                tool_registry,
                workspace,
                event_sink,
                scheduler,
                spec,
            )
            .await
            .expect("spawn child should succeed");

        let child_caps = supervisor
            .child_capabilities(child_id)
            .await
            .expect("child capabilities should be retained by the supervisor");

        // The child must inherit exactly the delegatable fs.read tool and
        // must NOT inherit the non-delegatable shell.exec tool.
        assert_eq!(
            child_caps.tools.tools.len(),
            1,
            "child must inherit exactly one tool (fs.read), got {:?}",
            child_caps.tools.tools.keys().collect::<Vec<_>>()
        );
        assert!(
            child_caps.tools.tools.contains_key(&fs_read_id),
            "fs.read must be inherited by the child"
        );
        assert!(
            !child_caps.tools.tools.contains_key(&shell_exec_id),
            "shell.exec must not be inherited by the child"
        );
    }

    /// Acceptance test (Task 6.8): `WorkspacePolicy::Inherit` hands the child
    /// runner the exact same `Arc<dyn Workspace>` as the parent's.
    #[tokio::test]
    async fn spawn_child_workspace_inherit_shares_parent_workspace() {
        let supervisor = AgentSupervisor::new(SessionId::new(), SessionCancellation::new());
        let (parent, fs_read_id) = parent_agent(supervisor.session_id);

        let workspace: Arc<dyn Workspace> =
            Arc::new(FakeWorkspace::new().with_file("data.txt", "hello"));
        let child_id = spawn_child_with_policy(
            &supervisor,
            &parent,
            fs_read_id,
            workspace.clone(),
            WorkspacePolicy::Inherit,
        )
        .await;

        let child_ws = supervisor
            .child_workspace(child_id)
            .await
            .expect("child workspace should be retained by the supervisor");

        // Inherit must pass the exact parent workspace Arc to the runner.
        assert!(
            Arc::ptr_eq(&workspace, &child_ws),
            "Inherit must reuse the parent's workspace Arc"
        );
        assert_eq!(child_ws.mode(), WorkspaceMode::Shared);
    }

    /// Acceptance test (Task 6.8): `WorkspacePolicy::ReadOnly` hands the child
    /// runner a write-rejecting view; reads still succeed.
    #[tokio::test]
    async fn spawn_child_workspace_readonly_rejects_writes() {
        let supervisor = AgentSupervisor::new(SessionId::new(), SessionCancellation::new());
        let (parent, fs_read_id) = parent_agent(supervisor.session_id);

        let workspace: Arc<dyn Workspace> =
            Arc::new(FakeWorkspace::new().with_file("data.txt", "hello"));
        let child_id = spawn_child_with_policy(
            &supervisor,
            &parent,
            fs_read_id,
            workspace,
            WorkspacePolicy::ReadOnly,
        )
        .await;

        let child_ws = supervisor
            .child_workspace(child_id)
            .await
            .expect("child workspace should be retained by the supervisor");

        assert_eq!(child_ws.mode(), WorkspaceMode::Isolated);
        let err = child_ws.write("data.txt", "overwritten").await.unwrap_err();
        assert!(matches!(err, WorkspaceError::Isolated));
        // Reads still work through the read-only view.
        assert_eq!(child_ws.read("data.txt").await.unwrap(), "hello");
    }

    /// Acceptance test (Task 6.10): `WorkspacePolicy::Snapshot` hands the child
    /// runner a copy in a temp directory; child edits are isolated from the
    /// parent's original root.
    #[tokio::test]
    async fn spawn_child_workspace_snapshot_isolates_writes() {
        let dir = tempfile::tempdir().unwrap();
        tokio::fs::write(dir.path().join("data.txt"), "original")
            .await
            .unwrap();

        let parent_ws: Arc<dyn Workspace> = Arc::new(FsWorkspace::new(dir.path().to_path_buf()));
        let supervisor = AgentSupervisor::new(SessionId::new(), SessionCancellation::new());
        let (parent, fs_read_id) = parent_agent(supervisor.session_id);

        let child_id = spawn_child_with_policy(
            &supervisor,
            &parent,
            fs_read_id,
            parent_ws.clone(),
            WorkspacePolicy::Snapshot,
        )
        .await;

        let child_ws = supervisor
            .child_workspace(child_id)
            .await
            .expect("child workspace should be retained by the supervisor");

        // The snapshot lives at a distinct root, not the parent's original.
        assert_ne!(child_ws.root(), parent_ws.root());

        // The child edits hit the snapshot root only...
        child_ws.write("data.txt", "child edit").await.unwrap();
        assert_eq!(child_ws.read("data.txt").await.unwrap(), "child edit");

        // ...leaving the parent's original root untouched.
        assert_eq!(parent_ws.read("data.txt").await.unwrap(), "original");
    }

    /// Acceptance test (Task 6.10): `WorkspacePolicy::NewWorktree` hands the
    /// child runner a real git worktree checked out under the repo root.
    #[tokio::test]
    async fn spawn_child_workspace_newworktree_is_real_checkout() {
        let repo_dir = tempfile::tempdir().unwrap();
        init_repo(repo_dir.path());

        let parent_ws: Arc<dyn Workspace> =
            Arc::new(FsWorkspace::new(repo_dir.path().to_path_buf()));
        let supervisor = AgentSupervisor::new(SessionId::new(), SessionCancellation::new());
        let (parent, fs_read_id) = parent_agent(supervisor.session_id);

        let child_id = spawn_child_with_policy(
            &supervisor,
            &parent,
            fs_read_id,
            parent_ws,
            WorkspacePolicy::NewWorktree,
        )
        .await;

        let child_ws = supervisor
            .child_workspace(child_id)
            .await
            .expect("child workspace should be retained by the supervisor");

        // The worktree must be a real directory on disk under `.harness-worktrees`.
        let root = child_ws.root().to_path_buf();
        assert!(
            root.is_dir(),
            "worktree must be a real directory on disk: {}",
            root.display()
        );
        assert!(root.starts_with(repo_dir.path().join(".harness-worktrees")));

        // The worktree is a writable checkout and reflects its own edits.
        child_ws.write("child.txt", "child change").await.unwrap();
        assert_eq!(child_ws.read("child.txt").await.unwrap(), "child change");
    }

    /// Build a throwaway git repository at `dir` containing a single committed
    /// file on `master`, so the worktree has a branch to check out.
    fn init_repo(dir: &Path) {
        let repo = git2::Repository::init(dir).unwrap();

        let mut index = repo.index().unwrap();
        std::fs::write(dir.join("README.md"), "# initial\n").unwrap();
        index.add_path(Path::new("README.md")).unwrap();
        index.write().unwrap();
        let tree_id = index.write_tree().unwrap();

        let sig = git2::Signature::now("Test", "test@example.com").unwrap();
        let tree = repo.find_tree(tree_id).unwrap();

        let parent = repo
            .head()
            .ok()
            .and_then(|head| head.peel_to_commit().ok());

        let commit_id = match parent {
            Some(parent) => repo
                .commit(
                    Some("HEAD"),
                    &sig,
                    &sig,
                    "initial commit",
                    &tree,
                    &[&parent],
                )
                .unwrap(),
            None => repo
                .commit(Some("HEAD"), &sig, &sig, "initial commit", &tree, &[])
                .unwrap(),
        };

        // Ensure master points at the new commit.
        repo.branch("master", &repo.find_commit(commit_id).unwrap(), true)
            .unwrap();
        repo.set_head("refs/heads/master").unwrap();
    }
}

