//! Async runtime loop for a single deterministic agent.

use std::collections::HashMap;
use std::sync::Arc;

use rust_decimal::Decimal;
use tokio::sync::{broadcast, mpsc};
use tokio_util::sync::CancellationToken;

use harness_core::agent::Agent;
use harness_protocol::backend::{ExecutionEvent, ExecutionRequest};
use harness_protocol::commands::{AgentCommand, AgentStatus};
use harness_protocol::effects::{AgentEffect, ToolRequest};
use harness_protocol::events::{AgentEvent, AgentEventEnvelope, AgentOutcome, EventVisibility};
use harness_protocol::ids::{AgentId, EventId, RunId, Timestamp, ToolCallId};

use crate::scheduler::Scheduler;
use crate::session_runtime::LiveStateTable;
use crate::traits::{EventSink, ExecutionBackend, ToolRegistry};

/// Mailbox and control handles for one agent.
pub struct AgentTask {
    pub id: AgentId,
    pub commands: mpsc::Receiver<AgentCommand>,
    /// Retained by the runner so asynchronous effect tasks can report results.
    pub commands_tx: mpsc::Sender<AgentCommand>,
    pub events: broadcast::Sender<AgentEventEnvelope>,
    pub cancel: CancellationToken,
}

impl AgentTask {
    /// Creates a mailbox and returns its external command sender.
    pub fn new(id: AgentId) -> (Self, mpsc::Sender<AgentCommand>) {
        let (commands_tx, commands) = mpsc::channel(64);
        let (events, _) = broadcast::channel(256);
        let task = Self {
            id,
            commands,
            commands_tx: commands_tx.clone(),
            events,
            cancel: CancellationToken::new(),
        };
        (task, commands_tx)
    }

    /// Creates a mailbox with caller-selected channel capacities.
    pub fn new_with_capacities(
        id: AgentId,
        command_capacity: usize,
        event_capacity: usize,
    ) -> (Self, mpsc::Sender<AgentCommand>) {
        let (commands_tx, commands) = mpsc::channel(command_capacity);
        let (events, _) = broadcast::channel(event_capacity);
        let task = Self {
            id,
            commands,
            commands_tx: commands_tx.clone(),
            events,
            cancel: CancellationToken::new(),
        };
        (task, commands_tx)
    }
}

/// Drives an agent state machine and dispatches its effects asynchronously.
pub struct AgentRunner {
    pub agent: Agent,
    pub task: AgentTask,
    pub backend: Arc<dyn ExecutionBackend>,
    pub tool_registry: Arc<dyn ToolRegistry>,
    pub event_sink: Arc<dyn EventSink>,
    pub agent_sequence: u64,
    pub cancel: CancellationToken,
    /// Concurrency throttle for backend requests, tool executions, etc.
    pub scheduler: Arc<Scheduler>,
    /// Shared table that this runner publishes its live status/usage into
    /// after every transition, so external readers (e.g.
    /// `SessionRuntime::agent_live_state`) always see a pure, up-to-date
    /// projection rather than a stale copy.
    live_state: LiveStateTable,
    backend_tokens: HashMap<RunId, CancellationToken>,
    tool_tokens: HashMap<ToolCallId, CancellationToken>,
}

impl AgentRunner {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        agent: Agent,
        mut task: AgentTask,
        backend: Arc<dyn ExecutionBackend>,
        tool_registry: Arc<dyn ToolRegistry>,
        event_sink: Arc<dyn EventSink>,
        cancel: CancellationToken,
        live_state: LiveStateTable,
        scheduler: Arc<Scheduler>,
    ) -> Self {
        task.cancel = cancel.clone();
        Self {
            agent,
            task,
            backend,
            tool_registry,
            event_sink,
            agent_sequence: 0,
            cancel,
            scheduler,
            live_state,
            backend_tokens: HashMap::new(),
            tool_tokens: HashMap::new(),
        }
    }

    /// Processes commands until completion, cancellation, or mailbox closure.
    pub async fn run(&mut self) {
        self.publish_status();
        loop {
            if self.cancel.is_cancelled() {
                if !self.is_terminal() {
                    let effects = self.apply_and_publish(AgentCommand::Cancel);
                    self.dispatch_effects(effects).await;
                }
                break;
            }

            let command = tokio::select! {
                command = self.task.commands.recv() => match command {
                    Some(command) => command,
                    None => break,
                },
                _ = self.cancel.cancelled() => {
                    if !self.is_terminal() {
                        let effects = self.apply_and_publish(AgentCommand::Cancel);
                        self.dispatch_effects(effects).await;
                    }
                    break;
                }
            };

            if self.cancel.is_cancelled() {
                if !self.is_terminal() {
                    let effects = self.apply_and_publish(AgentCommand::Cancel);
                    self.dispatch_effects(effects).await;
                }
                break;
            }

            let effects = self.apply_and_publish(command);
            if self.dispatch_effects(effects).await {
                break;
            }
        }
    }

    /// Applies `command` to the agent and immediately publishes the
    /// resulting status/operation/usage to the shared live-state table.
    fn apply_and_publish(&mut self, command: AgentCommand) -> Vec<AgentEffect> {
        let effects = self.agent.apply(command);
        self.publish_status();
        effects
    }

    /// Writes the agent's current status, operation, error, and usage into
    /// the shared live-state table.
    fn publish_status(&self) {
        let usage = harness_core::usage::compute_agent_usage_summary(&self.agent.usage.records, &[]);
        let total_cost_usd = self.agent.usage.records.iter().fold(None::<Decimal>, |acc, record| {
            match record.cost.amount_usd {
                Some(amount) => Some(acc.unwrap_or(Decimal::ZERO) + amount),
                None => acc,
            }
        });

        let mut table = self.live_state.lock().expect("live_state mutex poisoned");
        let entry = table.entry(self.agent.id).or_default();
        entry.status = self.agent.state.status;
        entry.current_operation = self.agent.state.current_operation.clone();
        entry.last_error = self.agent.state.last_error.clone();
        entry.usage = usage;
        entry.total_requests = self.agent.usage.records.len() as u64;
        entry.total_cost_usd = total_cost_usd;
    }

    /// Records the outcome of a finished run (Success/Cancelled/Failed) in
    /// the shared live-state table.
    ///
    /// `AgentStatus` returns to `Idle` after a successful run, so this is
    /// the only durable record that a run finished versus never having run.
    fn publish_outcome(&self, outcome: AgentOutcome) {
        let mut table = self.live_state.lock().expect("live_state mutex poisoned");
        let entry = table.entry(self.agent.id).or_default();
        entry.last_outcome = Some(outcome);
    }

    async fn dispatch_effects(&mut self, effects: Vec<AgentEffect>) -> bool {
        let mut finish = false;
        for effect in effects {
            match effect {
                AgentEffect::ExecuteBackend { request } => self.execute_backend(request).await,
                AgentEffect::ExecuteTool { request } => self.execute_tool(request).await,
                AgentEffect::Emit { event } => self.emit(event),
                AgentEffect::FinishRun { .. } => finish = true,
                AgentEffect::CancelBackend { run_id } => self.cancel_backend(run_id),
                AgentEffect::CancelTool { call_id } => self.cancel_tool(call_id),
                AgentEffect::CancelChild { agent_id } => {
                    tracing::warn!(?agent_id, "CancelChild is not wired in Phase 2");
                }
                AgentEffect::SpawnAgent { spec } => {
                    tracing::warn!(?spec, "SpawnAgent is not wired in Phase 2");
                }
                AgentEffect::RequestPermission { request } => {
                    tracing::warn!(?request, "RequestPermission is not wired in Phase 2");
                }
                AgentEffect::Persist { mutation } => {
                    tracing::warn!(?mutation, "Persist is not wired in Phase 2");
                }
            }
        }
        finish
    }

    fn emit(&mut self, event: AgentEvent) {
        match &event {
            AgentEvent::Completed { outcome } => self.publish_outcome(*outcome),
            AgentEvent::Failed { .. } => self.publish_outcome(AgentOutcome::Failed),
            _ => {}
        }

        let envelope = AgentEventEnvelope {
            event_id: EventId::new(),
            session_id: self.agent.session_id,
            agent_id: self.agent.id,
            parent_agent_id: self.agent.parent_id,
            run_id: self.agent.state.active_run,
            agent_sequence: self.agent_sequence,
            session_sequence: None,
            timestamp: Timestamp::now(),
            visibility: EventVisibility::User,
            event,
        };
        self.agent_sequence = self.agent_sequence.wrapping_add(1);
        // Send to the agent's own event broadcast channel (read by SessionEventBus).
        let _ = self.task.events.send(envelope.clone());
        // Forward to the external event sink (persistence, logging, etc.).
        self.event_sink.send(envelope);
    }

    /// Dispatches a backend execution effect.
    ///
    /// Acquires **both** a global backend permit from the [`Scheduler`] and a
    /// backend-specific permit (concurrency + rate-limit guard) before
    /// spawning the forwarding and driver tasks.  The permits are moved into
    /// the driver task and held for the entire duration of the backend
    /// request, throttling concurrent LLM API calls across all agents and
    /// enforcing per-backend rate limits.
    ///
    /// Two tasks cooperate here:
    ///
    /// 1. A **forwarding** task that drains `event_rx` and forwards each
    ///    streamed `ExecutionEvent` into the agent's own mailbox as it
    ///    arrives, so intermediate deltas are observed as they occur.
    /// 2. A **driver** task that awaits `backend.execute(..)` to
    ///    completion, then — crucially — awaits the forwarding task's
    ///    `JoinHandle` before injecting the final `Result` only when the
    ///    backend did not already stream a terminal event.
    ///
    /// The await on the forwarding task's handle is what guarantees
    /// ordering: `backend.execute` drops its `sink` sender when it
    /// returns, which closes the broadcast channel, which is exactly the
    /// signal the forwarding task uses to stop. Without waiting for it,
    /// a backend whose `execute` future never yields (e.g. `FakeBackend`
    /// or a purely synchronous scripted backend) can have its driver task
    /// enqueue the synthesized terminal event in the mailbox *before* the
    /// forwarding task — spawned but not yet polled — has forwarded the
    /// already-buffered intermediate events, causing them to be silently
    /// dropped once the agent's `active_run` guard clears on the terminal
    /// event. Waiting for the forwarding task to finish first eliminates
    /// that race regardless of scheduler ordering.
    async fn execute_backend(&mut self, request: ExecutionRequest) {
        // Acquire the global backend semaphore permit.
        let global_permit = self.scheduler.acquire_backend_permit().await;

        // Acquire the backend-specific permit (concurrency slot + rate-limit
        // guard).  This is a no-op if no limits were configured for this
        // backend via Scheduler::configure_backend_limits.
        let backend_id = self.backend.descriptor().id;
        let backend_guard = self
            .scheduler
            .acquire_backend_specific_permit(backend_id)
            .await;

        let run_id = request.run_id;
        let request_id = request.request_id;
        let (event_tx, mut event_rx) = broadcast::channel(256);
        let token = self.cancel.child_token();
        self.backend_tokens.insert(run_id, token.clone());

        let commands = self.task.commands_tx.clone();
        let forward_cancel = self.cancel.clone();
        let forward_handle = tokio::spawn(async move {
            let mut terminal_forwarded = false;
            loop {
                tokio::select! {
                    event = event_rx.recv() => match event {
                        Ok(event) => {
                            terminal_forwarded |= matches!(
                                &event,
                                ExecutionEvent::Completed { .. } | ExecutionEvent::Error { .. }
                            );
                            if commands.send(AgentCommand::BackendEvent { run_id, event }).await.is_err() {
                                break;
                            }
                        }
                        Err(broadcast::error::RecvError::Closed) => break,
                        Err(broadcast::error::RecvError::Lagged(n)) => {
                            tracing::warn!(run_id = ?run_id, skipped = n, "backend event receiver lagged");
                        }
                    },
                    _ = forward_cancel.cancelled() => break,
                }
            }
            terminal_forwarded
        });

        let backend = self.backend.clone();
        let result_commands = self.task.commands_tx.clone();
        let result_token = token.clone();
        tokio::spawn(async move {
            // Hold both permits for the complete backend request lifecycle.
            // The forwarding task must not lock these permits: it needs to
            // receive events while the driver is executing the backend.
            let _global_permit = global_permit;
            let _backend_guard = backend_guard;
            let outcome = backend.execute(request, event_tx, result_token).await;
            // Ensure every already-streamed event has been forwarded to the
            // mailbox before injecting the synthesized terminal event (see
            // the doc comment above for why this ordering matters).
            let terminal_forwarded = forward_handle.await.unwrap_or(false);
            if !terminal_forwarded {
                let event = match outcome {
                    Ok(result) => ExecutionEvent::Completed { request_id, result },
                    Err(error) => ExecutionEvent::Error { request_id, error },
                };
                let _ = result_commands
                    .send(AgentCommand::BackendEvent { run_id, event })
                    .await;
            }
        });
    }

    /// Dispatches a tool execution effect.
    ///
    /// Acquires a tool permit from the [`Scheduler`] before spawning the
    /// execution task. The permit is moved into the spawned task and held
    /// for the entire tool execution, throttling concurrent tool calls
    /// across all agents.
    async fn execute_tool(&mut self, request: ToolRequest) {
        // Throttle tool executions — block if at capacity.
        let permit = self.scheduler.acquire_tool_permit().await;

        let call_id = request.call.id;
        let name = request.call.name.clone();
        let arguments = request.call.arguments.clone();
        let token = self.cancel.child_token();
        self.tool_tokens.insert(call_id, token.clone());
        let commands = self.task.commands_tx.clone();

        match self.tool_registry.get_executor(&name) {
            Some(executor) => {
                tokio::spawn(async move {
                    // Hold the permit for the duration of tool execution.
                    let _permit = permit;
                    // Convert protocol ToolCall to harness-tools ToolInput
                    let input = harness_tools::ToolInput {
                        arguments,
                    };

                    match executor.execute(input, token).await {
                        Ok(tool_result) => {
                            // Convert harness-tools ToolResult to protocol ToolResult
                            let result = harness_protocol::tools::ToolResult {
                                call_id,
                                output: tool_result.output,
                                is_error: tool_result.is_error,
                            };
                            let _ = commands.send(AgentCommand::ToolCompleted { call_id, result }).await;
                        }
                        Err(tool_error) => {
                            // Convert harness-tools ToolError to protocol ToolError
                            let error = match tool_error {
                                harness_tools::ToolError::ExecutionFailed => {
                                    harness_protocol::tools::ToolError::ExecutionFailed
                                }
                                harness_tools::ToolError::PermissionDenied => {
                                    harness_protocol::tools::ToolError::PermissionDenied
                                }
                                harness_tools::ToolError::Timeout => {
                                    harness_protocol::tools::ToolError::Timeout
                                }
                                harness_tools::ToolError::Internal => {
                                    harness_protocol::tools::ToolError::Internal
                                }
                            };
                            let _ = commands.send(AgentCommand::ToolFailed { call_id, error }).await;
                        }
                    }
                });
            }
            None => {
                tokio::spawn(async move {
                    let _permit = permit;
                    let _ = commands.send(AgentCommand::ToolFailed {
                        call_id,
                        error: harness_protocol::tools::ToolError::ExecutionFailed,
                    }).await;
                });
            }
        }
    }

    fn cancel_backend(&mut self, run_id: RunId) {
        if let Some(token) = self.backend_tokens.remove(&run_id) {
            token.cancel();
        }
    }

    fn cancel_tool(&mut self, call_id: ToolCallId) {
        if let Some(token) = self.tool_tokens.remove(&call_id) {
            token.cancel();
        }
    }

    fn is_terminal(&self) -> bool {
        matches!(
            self.agent.state.status,
            AgentStatus::Cancelled | AgentStatus::Completed | AgentStatus::Failed
        )
    }
}

#[cfg(test)]
mod tests {
    use std::collections::HashMap as StdHashMap;
    use std::sync::Mutex;
    use std::time::Duration;

    use harness_core::capabilities::{AgentCapabilities, WorkspaceCapabilities};
    use harness_protocol::backend::{
        BackendBinding, BackendCapabilities, BackendDescriptor, BackendReference,
    };
    use harness_protocol::commands::UserInput;
    use harness_protocol::ids::{BackendId, ConfigurationId, IntegrationId, SessionId};
    use harness_protocol::tools::AgentToolset;
    use harness_protocol::usage::AgentBudget;

    use crate::scheduler::{Scheduler, SchedulerConfig};
    use crate::testing::{FakeBackend, FakeToolRegistry};

    use super::*;

    #[tokio::test]
    async fn send_command_through_mailbox() {
        let (mut task, sender) = AgentTask::new(AgentId::new());
        sender.send(AgentCommand::Cancel).await.expect("send command");
        assert!(matches!(task.commands.recv().await, Some(AgentCommand::Cancel)));
    }

    struct NoopSink;
    impl EventSink for NoopSink {
        fn send(&self, _envelope: AgentEventEnvelope) {}
    }

    fn test_agent(agent_id: AgentId, session_id: SessionId) -> Agent {
        Agent::new(
            agent_id,
            session_id,
            None,
            String::new(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: "fake".into(),
                    description: "fake".into(),
                    capabilities: BackendCapabilities::default(),
                },
            },
            AgentCapabilities {
                tools: AgentToolset {
                    tools: StdHashMap::new(),
                },
                can_spawn_agents: false,
                max_child_depth: None,
                workspace: WorkspaceCapabilities {
                    can_read: false,
                    can_write: false,
                    can_search: false,
                },
                backend: BackendCapabilities::default(),
            },
            AgentBudget::default(),
        )
    }

    /// Task 2.3 acceptance criterion: start a `FakeBackend` call that blocks
    /// until cancelled, cancel the token mid-flight, and assert the runner
    /// transitions the agent to `Cancelled` and stops emitting further
    /// backend events.
    #[tokio::test]
    async fn cancel_mid_flight_backend_call_transitions_to_cancelled() {
        let agent_id = AgentId::new();
        let session_id = SessionId::new();
        let agent = test_agent(agent_id, session_id);

        let (task, sender) = AgentTask::new(agent_id);
        let backend = Arc::new(FakeBackend::new().blocking_until_cancelled());
        let tool_registry = Arc::new(FakeToolRegistry::new());
        let cancel = CancellationToken::new();
        let live_state: LiveStateTable = Arc::new(Mutex::new(StdHashMap::new()));
        let scheduler = Arc::new(Scheduler::new(SchedulerConfig::default()));

        let mut runner = AgentRunner::new(
            agent,
            task,
            backend,
            tool_registry,
            Arc::new(NoopSink),
            cancel.clone(),
            live_state.clone(),
            scheduler,
        );

        let mut events_rx = runner.task.events.subscribe();

        sender
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "hi".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        let run_handle = tokio::spawn(async move {
            runner.run().await;
            runner
        });

        // Give the runner time to process StartRun and spawn the (blocking)
        // backend call before we cancel mid-flight.
        tokio::time::sleep(Duration::from_millis(50)).await;

        // Mid-flight cancellation.
        cancel.cancel();

        let runner = tokio::time::timeout(Duration::from_secs(2), run_handle)
            .await
            .expect("runner should stop promptly after cancellation")
            .expect("runner task should not panic");

        assert_eq!(
            runner.agent.state.status,
            AgentStatus::Cancelled,
            "agent should transition to Cancelled after mid-flight cancellation"
        );

        // The live-state table should also reflect Cancelled.
        let live = live_state
            .lock()
            .expect("live_state mutex poisoned")
            .get(&agent_id)
            .cloned()
            .expect("live state entry exists");
        assert_eq!(live.status, AgentStatus::Cancelled);

        while events_rx.try_recv().is_ok() {}
        assert!(matches!(
            events_rx.try_recv(),
            Err(broadcast::error::TryRecvError::Empty)
        ));
    }
}

//! Hierarchical agent supervision for a single session.
//!
//! The [`AgentSupervisor`] owns the live registry of running agents for one
//! session: which agent is a child of which parent, each agent's nesting
//! depth, its cancellation token, and its spawned task handle. It is the sole
//! production entry point for spawning sub-agents in this phase (spec §21);
//! core-driven triggers such as `AgentEffect::SpawnAgent` remain a reserved
//! data shape for a future `agent.spawn` tool.
//!
//! Spawning is gated by [`max_children_depth_check`](AgentSupervisor::max_children_depth_check),
//! which enforces the parent's `max_children`/`max_depth` budget **before** any
//! child task is created, and then performed by
//! [`spawn_child`](AgentSupervisor::spawn_child) which runs the 8-step flow
//! from spec §21.
//!
//! Once spawned, a child can be driven in one of two ways via
//! [`spawn_and_drive`](AgentSupervisor::spawn_and_drive):
//!
//! * **Concurrent** — [`spawn_and_drive`] returns
//!   [`SpawnOutcome::Detached`] immediately with the child's [`AgentId`],
//!   leaving the child running in the background.
//! * **AwaitResult** — [`spawn_and_drive`] blocks until the child's runner
//!   terminates (via [`await_child`](AgentSupervisor::await_child)) and returns
//!   [`SpawnOutcome::Awaited`] carrying the child's final [`AgentResult`],
//!   which the spawned task delivers over a one-shot channel.

use std::collections::HashMap;
use std::sync::Arc;

use harness_core::agent::Agent;
use harness_core::budget::{BudgetCheck, BudgetError};
use harness_core::capabilities::{AgentCapabilities, CapabilityError};
use harness_protocol::backend::{BackendBinding, BackendDescriptor};
use harness_protocol::commands::{AgentCommand, AgentResult};
use harness_protocol::effects::{BackendPolicy, SpawnAgentSpec, SpawnMode};
use harness_protocol::ids::{AgentId, BackendId, SessionId};
use harness_protocol::usage::AgentBudget;
use tokio::sync::{mpsc, oneshot, RwLock};
use tokio::task::JoinHandle;
use tokio_util::sync::CancellationToken;

use crate::agent_runner::{AgentRunner, AgentTask};
use crate::cancellation::SessionCancellation;
use crate::integration::IntegrationRegistry;
use crate::scheduler::Scheduler;
use crate::session_runtime::LiveStateTable;
use crate::traits::{EventSink, ExecutionBackend, ToolRegistry, Workspace};

// ---------------------------------------------------------------------------
// AgentHandle
// ---------------------------------------------------------------------------

/// Bookkeeping for a single live agent tracked by the supervisor.
struct AgentHandle {
    parent_id: Option<AgentId>,
    depth: u32,
    cancel: CancellationToken,
    join: JoinHandle<()>,
    /// Sender used to drive the child's mailbox (start runs, cancel, etc.)
    /// from outside the child's own runner.
    commands: mpsc::Sender<AgentCommand>,
    /// Receiver for the child's final [`AgentResult`], delivered by the
    /// spawned task once its runner terminates. Consumed by
    /// [`await_child`](AgentSupervisor::await_child) so the parent can block
    /// on a child that was spawned with [`SpawnMode::AwaitResult`].
    result: oneshot::Receiver<AgentResult>,
}

// ---------------------------------------------------------------------------
// SpawnOutcome
// ---------------------------------------------------------------------------

/// The result of a [`spawn_and_drive`](AgentSupervisor::spawn_and_drive) call.
///
/// Mirrors [`SpawnMode`]: an awaited child yields its final [`AgentResult`],
/// while a concurrent child is returned detached (its [`AgentId`]) so the
/// caller can continue without blocking on it.
#[derive(Debug, Clone)]
pub enum SpawnOutcome {
    /// The child completed and its final result was retrieved.
    Awaited(AgentResult),
    /// The child was spawned and is running in the background.
    Detached(AgentId),
}

// ---------------------------------------------------------------------------
// SupervisorError
// ---------------------------------------------------------------------------

/// Errors surfaced while supervising agent spawning and lifecycle.
#[derive(Debug, thiserror::Error)]
pub enum SupervisorError {
    #[error("budget: {0}")]
    Budget(#[from] BudgetError),
    #[error("capability: {0}")]
    Capability(#[from] CapabilityError),
    #[error("parent agent not found: {0:?}")]
    ParentNotFound(AgentId),
    #[error("child {0:?} finished without producing a result")]
    ChildResultLost(AgentId),
}

// ---------------------------------------------------------------------------
// AgentSupervisor
// ---------------------------------------------------------------------------

/// The live registry of agents for a single session.
pub struct AgentSupervisor {
    session_id: SessionId,
    session_cancel: SessionCancellation,
    /// Child → handle registry (every tracked agent).
    agents: RwLock<HashMap<AgentId, AgentHandle>>,
    /// Parent → direct child IDs, used for `max_children` accounting.
    children_of: RwLock<HashMap<AgentId, Vec<AgentId>>>,
    /// Capabilities granted to each spawned child, retained so callers can
    /// inspect them (e.g. verifying the non-escalation invariant in tests).
    child_capabilities: RwLock<HashMap<AgentId, AgentCapabilities>>,
}

impl AgentSupervisor {
    /// Creates an empty supervisor scoped to a session.
    pub fn new(session_id: SessionId, session_cancel: SessionCancellation) -> Self {
        Self {
            session_id,
            session_cancel,
            agents: RwLock::new(HashMap::new()),
            children_of: RwLock::new(HashMap::new()),
            child_capabilities: RwLock::new(HashMap::new()),
        }
    }

    /// Enforces the parent's `max_children` and `max_depth` budget **before**
    /// a child task is created.
    ///
    /// (a) counts the parent's current live children from [`children_of`],
    /// (b) calls [`BudgetCheck::check_children`] with that count, then
    /// (c) calls [`BudgetCheck::check_depth`] with the parent's depth.
    pub async fn max_children_depth_check(
        &self,
        parent_id: AgentId,
        parent_depth: u32,
        parent_budget: &AgentBudget,
    ) -> Result<(), SupervisorError> {
        let children = self.children_of.read().await;
        let current = children.get(&parent_id).map(|v| v.len()).unwrap_or(0) as u32;
        parent_budget.check_children(current)?;
        parent_budget.check_depth(parent_depth)?;
        Ok(())
    }

    /// Spawns a child agent of `parent` following the 8-step flow from spec
    /// §21 and returns the new child's [`AgentId`] on success.
    ///
    /// 1. **Gating** — [`max_children_depth_check`](Self::max_children_depth_check)
    ///    rejects the spawn if the parent is at its `max_children`/`max_depth`
    ///    limit.
    /// 2. **Backend resolution** — `BackendPolicy::Inherit` reuses
    ///    `parent_backend`; `BackendPolicy::Explicit` resolution is deferred
    ///    to a later task (currently falls back to the parent backend).
    /// 3. **Capability inheritance** — derives the child's full
    ///    [`AgentCapabilities`] (tools, spawning, depth) via the
    ///    non-escalation-enforcing `derive_child_agent_capabilities`.
    /// 4. **Workspace resolution** — all modes are deferred to a later task;
    ///    currently stubbed to inherit the parent's workspace.
    /// 5. **Budget** — the child inherits `spec.budget` as-is.
    /// 6. **Cancellation** — a fresh child token is derived from the session
    ///    cancellation root.
    /// 7. **Construct** — builds the child [`Agent`], its [`AgentTask`], and
    ///    an [`AgentRunner`].
    /// 8. **Spawn & register** — runs the runner as a tokio task and records
    ///    it in the registry, along with the child's command sender and the
    ///    receiver of its one-shot result channel.
    #[allow(clippy::too_many_arguments)]
    pub async fn spawn_child(
        &self,
        parent: &Agent,
        parent_backend: Arc<dyn ExecutionBackend>,
        integration_registry: &IntegrationRegistry,
        tool_registry: Arc<dyn ToolRegistry>,
        workspace: Arc<dyn Workspace>,
        event_sink: Arc<dyn EventSink>,
        scheduler: Arc<Scheduler>,
        spec: SpawnAgentSpec,
    ) -> Result<AgentId, SupervisorError> {
        // 1. Gating: enforce the parent's max_children/max_depth budget before
        //    any child task is created. Depth tracking is not yet threaded
        //    through `Agent` (a separate task), so the parent is gated at
        //    depth 0 and children are registered at depth 1.
        let parent_depth = 0u32;
        self.max_children_depth_check(parent.id, parent_depth, &parent.budget)
            .await?;

        // 2. Backend resolution. `BackendPolicy::Explicit` resolution via the
        //    integration registry is deferred to a later task (T6.6); for now
        //    both policies resolve to the parent's backend.
        let backend = match &spec.backend {
            BackendPolicy::Inherit => parent_backend.clone(),
            BackendPolicy::Explicit(_reference) => parent_backend.clone(),
        };

        // 3. Capability/tool inheritance with non-escalation enforcement.
        let capabilities = parent
            .capabilities
            .derive_child_agent_capabilities(&spec.tools, None, None)?;

        // 4. Workspace resolution. All modes are deferred to a later task
        //    (T6.8/T6.10); for now the child inherits the parent's workspace.
        let _child_workspace = workspace.clone();

        // 5. Budget = `spec.budget` as-is (explicit override is the caller's
        //    responsibility per spec).

        // 6. Cancellation: derive a fresh token from the session root.
        let child_cancel = self.session_cancel.child_token();

        // 7. Construct the child Agent, its mailbox, and its runner.
        let child_id = AgentId::new();
        let child_depth = parent_depth + 1;
        let child_agent = Agent::new(
            child_id,
            parent.session_id,
            Some(parent.id),
            spec.role.clone().unwrap_or_default(),
            BackendBinding {
                reference: parent.backend.reference.clone(),
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: backend.descriptor().name,
                    description: backend.descriptor().description,
                    capabilities: backend.capabilities(),
                },
            },
            capabilities.clone(),
            spec.budget.clone(),
        );

        let (task, commands_tx) = AgentTask::new(child_id);
        // Result-capture channel: the spawned task sends the child's final
        // `AgentResult` over `result_tx` once its runner terminates; the
        // receiver is stored in the registry so `await_child` can block on it.
        let (result_tx, result_rx) = oneshot::channel::<AgentResult>();
        let mut runner = AgentRunner::new(
            child_agent,
            task,
            backend,
            tool_registry,
            event_sink,
            child_cancel.clone(),
            LiveStateTable::default(),
            scheduler,
        );

        // 8. Spawn the runner as an independent tokio task and register it.
        let join = tokio::spawn(async move {
            runner.run().await;
            // Derive a final result from the child's terminal state. The
            // runner does not yet expose its captured `FinishRun` result (a
            // later task wires that up); for now the supervisor reports the
            // status the child finished in, which is sufficient for
            // `SpawnMode::AwaitResult` callers.
            let result = AgentResult {
                summary: format!(
                    "child {} finished with status {:?}",
                    child_id, runner.agent.state.status
                ),
                usage: Default::default(),
            };
            let _ = result_tx.send(result);
        });
        self.register(
            Some(parent.id),
            child_id,
            child_depth,
            child_cancel,
            join,
            commands_tx,
            result_rx,
        )
        .await;

        // Retain the granted capabilities for inspection (e.g. the
        // non-escalation integration test).
        self.child_capabilities
            .write()
            .await
            .insert(child_id, capabilities);

        Ok(child_id)
    }

    /// Spawns a child and drives it to completion (or detaches it) according
    /// to [`SpawnMode`].
    ///
    /// * [`SpawnMode::Concurrent`] — spawns the child and immediately returns
    ///   [`SpawnOutcome::Detached`] with its [`AgentId`]; the child continues
    ///   executing in the background.
    /// * [`SpawnMode::AwaitResult`] — spawns the child and blocks (via
    ///   [`await_child`](Self::await_child)) until its runner terminates,
    ///   returning [`SpawnOutcome::Awaited`] with the child's final
    ///   [`AgentResult`].
    #[allow(clippy::too_many_arguments)]
    pub async fn spawn_and_drive(
        &self,
        parent: &Agent,
        parent_backend: Arc<dyn ExecutionBackend>,
        integration_registry: &IntegrationRegistry,
        tool_registry: Arc<dyn ToolRegistry>,
        workspace: Arc<dyn Workspace>,
        event_sink: Arc<dyn EventSink>,
        scheduler: Arc<Scheduler>,
        spec: SpawnAgentSpec,
    ) -> Result<SpawnOutcome, SupervisorError> {
        let mode = spec.mode;
        let child_id = self
            .spawn_child(
                parent,
                parent_backend,
                integration_registry,
                tool_registry,
                workspace,
                event_sink,
                scheduler,
                spec,
            )
            .await?;
        match mode {
            SpawnMode::Concurrent => Ok(SpawnOutcome::Detached(child_id)),
            SpawnMode::AwaitResult => {
                let result = self.await_child(child_id).await?;
                Ok(SpawnOutcome::Awaited(result))
            }
        }
    }

    /// Joins a previously spawned child task and retrieves its final
    /// [`AgentResult`] over the child's one-shot result channel.
    ///
    /// This is the blocking half of [`SpawnMode::AwaitResult`]: it removes the
    /// child from the registry (releasing the parent's `max_children` slot),
    /// waits for the spawned runner task to terminate, and then reads the
    /// [`AgentResult`] the task delivered. Returns
    /// [`SupervisorError::ChildResultLost`] if the child finished without
    /// delivering a result.
    pub async fn await_child(&self, child_id: AgentId) -> Result<AgentResult, SupervisorError> {
        // Remove the handle so we can take ownership of its join handle and
        // result receiver, and so the parent's child slot is released.
        let mut agents = self.agents.write().await;
        let handle = agents
            .remove(&child_id)
            .ok_or(SupervisorError::ChildResultLost(child_id))?;
        drop(agents);

        // Release the child from the parent's `children_of` accounting.
        if let Some(pid) = handle.parent_id {
            let mut children = self.children_of.write().await;
            if let Some(v) = children.get_mut(&pid) {
                v.retain(|c| *c != child_id);
            }
        }

        // Join the spawned child task, then retrieve the final result.
        let _ = handle.join.await;
        let result = handle
            .result
            .await
            .map_err(|_| SupervisorError::ChildResultLost(child_id))?;
        Ok(result)
    }

    /// Returns the [`AgentCapabilities`] granted to a previously spawned child,
    /// if it was created by this supervisor.
    pub async fn child_capabilities(&self, child_id: AgentId) -> Option<AgentCapabilities> {
        self.child_capabilities
            .read()
            .await
            .get(&child_id)
            .cloned()
    }

    /// Records a child agent in the registry and links it under its parent.
    #[allow(clippy::too_many_arguments)]
    async fn register(
        &self,
        parent_id: Option<AgentId>,
        child_id: AgentId,
        depth: u32,
        cancel: CancellationToken,
        join: JoinHandle<()>,
        commands: mpsc::Sender<AgentCommand>,
        result: oneshot::Receiver<AgentResult>,
    ) {
        let mut agents = self.agents.write().await;
        let mut children = self.children_of.write().await;
        agents.insert(
            child_id,
            AgentHandle {
                parent_id,
                depth,
                cancel,
                join,
                commands,
                result,
            },
        );
        if let Some(pid) = parent_id {
            children.entry(pid).or_insert_with(Vec::new).push(child_id);
        }
    }

    /// Removes a completed agent from the registry and from its parent's
    /// child list.
    async fn deregister(&self, child_id: AgentId) {
        let mut agents = self.agents.write().await;
        if let Some(handle) = agents.remove(&child_id) {
            if let Some(pid) = handle.parent_id {
                let mut children = self.children_of.write().await;
                if let Some(v) = children.get_mut(&pid) {
                    v.retain(|c| *c != child_id);
                }
            }
        }
    }
}

