//! Deterministic agent state transitions. The core mutates state and emits effects only.

use harness_protocol::backend::{ExecutionEvent, ExecutionRequest};
use harness_protocol::commands::{
    AgentCommand, AgentError, AgentResult, AgentStatus, PermissionDecision, UserInput,
};
use harness_protocol::effects::{AgentEffect, PermissionRequest, ToolRequest};
use harness_protocol::events::{AgentEvent, AgentOutcome};
use harness_protocol::ids::{
    AgentId, MessageId, PermissionId, RequestId, RunId, Timestamp, ToolCallId,
};
use harness_protocol::messages::{AgentMessage, ContentBlock, MessageRole};
use harness_protocol::tools::{PermissionMode, ToolCall, ToolError, ToolResult, ToolResultSummary};
use harness_protocol::usage::{AgentUsageSummary, UsageRecord};

use crate::agent::Agent;
use crate::agent_state::PendingToolCall;
use crate::transcript::validate_transcript;

impl Agent {
    pub fn apply(&mut self, command: AgentCommand) -> Vec<AgentEffect> {
        match command {
            AgentCommand::StartRun { input } => self.start_run(input),
            AgentCommand::BackendEvent { run_id, event } => self.backend_event(run_id, event),
            AgentCommand::ToolCompleted { call_id, result } => self.tool_completed(call_id, result),
            AgentCommand::ToolFailed { call_id, error } => self.tool_failed(call_id, error),
            AgentCommand::PermissionResolved { id, decision } => {
                self.permission_resolved(id, decision)
            }
            AgentCommand::ChildCompleted { agent_id, result } => {
                self.child_completed(agent_id, result)
            }
            AgentCommand::ChildFailed { agent_id, error } => self.child_failed(agent_id, error),
            AgentCommand::Cancel => self.cancel(),
            AgentCommand::Pause => self.pause(),
            AgentCommand::Resume => self.resume(),
        }
    }

    fn take_sequence(&mut self) -> u64 {
        let current = self.state.transition_sequence;
        self.state.transition_sequence = current.saturating_add(1);
        current
    }

    fn next_run_id(&mut self) -> RunId {
        RunId::derived(self.id.as_uuid(), self.take_sequence(), 1)
    }

    fn next_request_id(&mut self) -> RequestId {
        RequestId::derived(self.id.as_uuid(), self.take_sequence(), 2)
    }

    fn next_message_id(&mut self) -> MessageId {
        MessageId::derived(self.id.as_uuid(), self.take_sequence(), 3)
    }

    fn next_permission_id(&mut self) -> PermissionId {
        PermissionId::derived(self.id.as_uuid(), self.take_sequence(), 4)
    }

    fn next_timestamp(&mut self) -> Timestamp {
        Timestamp::from_sequence(self.take_sequence())
    }

    fn execution_request(&mut self, run_id: RunId) -> ExecutionRequest {
        let tools = self
            .capabilities
            .tools
            .enabled_descriptors()
            .into_iter()
            .cloned()
            .collect();
        ExecutionRequest {
            request_id: self.next_request_id(),
            run_id,
            system_prompt: self.state.system_prompt.clone(),
            messages: self.state.messages.clone(),
            tools,
            extended_thinking: false,
        }
    }

    fn state_changed(from: AgentStatus, to: AgentStatus) -> AgentEffect {
        AgentEffect::Emit {
            event: AgentEvent::StateChanged { from, to },
        }
    }

    fn fail(&mut self, code: &str, message: String) -> Vec<AgentEffect> {
        let from = self.state.status;
        let error = AgentError {
            message,
            code: code.into(),
            details: None,
        };
        self.state.status = AgentStatus::Failed;
        self.state.active_run = None;
        self.state.last_error = Some(error.clone());
        vec![
            Self::state_changed(from, AgentStatus::Failed),
            AgentEffect::Emit {
                event: AgentEvent::Failed {
                    error: error.clone(),
                },
            },
            AgentEffect::FinishRun {
                result: AgentResult {
                    summary: error.message,
                    usage: AgentUsageSummary::default(),
                },
            },
        ]
    }

    fn start_run(&mut self, input: UserInput) -> Vec<AgentEffect> {
        if let Err(error) = validate_transcript(&self.state.messages) {
            return self.fail("INVALID_TRANSCRIPT", error.to_string());
        }
        let from = self.state.status;
        let run_id = self.next_run_id();
        let message_id = self.next_message_id();
        let created_at = self.next_timestamp();
        self.state.messages.push(AgentMessage {
            id: message_id,
            role: MessageRole::User,
            content: vec![ContentBlock::Text { text: input.text }],
            created_at,
        });
        self.state.status = AgentStatus::PreparingContext;
        self.state.active_run = Some(run_id);
        let request = self.execution_request(run_id);
        vec![
            Self::state_changed(from, AgentStatus::PreparingContext),
            AgentEffect::ExecuteBackend { request },
            AgentEffect::Emit {
                event: AgentEvent::RunStarted { run_id },
            },
        ]
    }

    fn backend_event(&mut self, run_id: RunId, event: ExecutionEvent) -> Vec<AgentEffect> {
        if self.state.active_run != Some(run_id) {
            return Vec::new();
        }
        match event {
            ExecutionEvent::TextDelta { delta, .. } => {
                let from = self.state.status;
                self.state.status = AgentStatus::Streaming;
                let message_id = self.append_assistant_text(&delta);
                let mut effects = Vec::new();
                if from != AgentStatus::Streaming {
                    effects.push(Self::state_changed(from, AgentStatus::Streaming));
                }
                effects.push(AgentEffect::Emit {
                    event: AgentEvent::AssistantTextDelta { message_id, delta },
                });
                effects
            }
            ExecutionEvent::ReasoningDelta { delta, .. } => {
                let message_id = self.assistant_message_id();
                vec![AgentEffect::Emit {
                    event: AgentEvent::ReasoningDelta { message_id, delta },
                }]
            }
            ExecutionEvent::ToolCallRequested { call, .. } => self.tool_requested(call),
            // Usage updates are cumulative snapshots for observability. The
            // terminal result below is the single authoritative ledger record
            // for a model request.
            ExecutionEvent::UsageUpdate { .. } => Vec::new(),
            ExecutionEvent::Completed { result, .. } => {
                let is_tool_turn = result.finish_reason == "tool_use";
                self.usage.records.push(UsageRecord {
                    model_usage: result.usage,
                    cost: result.cost,
                    tool_usage: None,
                });
                if is_tool_turn {
                    // The model request is complete, but the agent run is not:
                    // tool results will trigger the next backend request.
                    return Vec::new();
                }
                let from = self.state.status;
                self.state.status = AgentStatus::Idle;
                self.state.active_run = None;
                vec![
                    Self::state_changed(from, AgentStatus::Idle),
                    AgentEffect::Emit {
                        event: AgentEvent::Completed {
                            outcome: AgentOutcome::Success,
                        },
                    },
                    AgentEffect::FinishRun {
                        result: AgentResult {
                            summary: format!("Run completed: {}", result.finish_reason),
                            usage: AgentUsageSummary::default(),
                        },
                    },
                ]
            }
            ExecutionEvent::Error { error, .. } => {
                self.fail("BACKEND_ERROR", format!("{error:?}"))
            }
        }
    }

    fn tool_requested(&mut self, call: ToolCall) -> Vec<AgentEffect> {
        let call_id = call.id;
        let message_id = self.next_message_id();
        let created_at = self.next_timestamp();
        self.state.messages.push(AgentMessage {
            id: message_id,
            role: MessageRole::Assistant,
            content: vec![ContentBlock::ToolUse { call: call.clone() }],
            created_at,
        });
        let started_at = self.next_timestamp();
        self.state.pending_tools.insert(
            call_id,
            PendingToolCall {
                call: call.clone(),
                started_at,
            },
        );
        let permission = self
            .capabilities
            .tools
            .tools
            .values()
            .find(|capability| {
                capability.descriptor.name == call.name && capability.policy.enabled
            })
            .map(|capability| capability.policy.permission.clone());
        let mut effects = vec![AgentEffect::Emit {
            event: AgentEvent::ToolCallRequested { call: call.clone() },
        }];
        match permission {
            Some(PermissionMode::Allow) => {
                self.state.status = AgentStatus::Executing;
                effects.push(AgentEffect::ExecuteTool {
                    request: ToolRequest {
                        call,
                        permission: PermissionMode::Allow,
                    },
                });
            }
            Some(PermissionMode::Ask) => {
                self.state.status = AgentStatus::WaitingForPermission;
                let permission_id = self.next_permission_id();
                self.state.pending_permissions.insert(permission_id, call_id);
                let request = PermissionRequest {
                    id: permission_id,
                    tool_call: call,
                    agent_id: self.id,
                };
                effects.push(AgentEffect::Emit {
                    event: AgentEvent::PermissionRequested {
                        request: request.clone(),
                    },
                });
                effects.push(AgentEffect::RequestPermission { request });
            }
            Some(PermissionMode::Deny) | None => {
                effects.extend(self.tool_failed(call_id, ToolError::PermissionDenied));
            }
        }
        effects
    }

    fn tool_completed(&mut self, call_id: ToolCallId, result: ToolResult) -> Vec<AgentEffect> {
        if self.state.pending_tools.remove(&call_id).is_none() {
            return Vec::new();
        }
        self.state.pending_permissions.retain(|_, id| *id != call_id);
        self.record_tool_result(call_id, result.is_error, serde_json::to_string(&result.output).unwrap_or_default())
    }

    fn tool_failed(&mut self, call_id: ToolCallId, error: ToolError) -> Vec<AgentEffect> {
        if self.state.pending_tools.remove(&call_id).is_none() {
            return Vec::new();
        }
        self.state.pending_permissions.retain(|_, id| *id != call_id);
        self.record_tool_result(call_id, true, format!("{error:?}"))
    }

    fn record_tool_result(
        &mut self,
        call_id: ToolCallId,
        has_error: bool,
        preview: String,
    ) -> Vec<AgentEffect> {
        let message_id = self.next_message_id();
        let created_at = self.next_timestamp();
        self.state.messages.push(AgentMessage {
            id: message_id,
            role: MessageRole::Tool,
            content: vec![ContentBlock::ToolResult {
                call_id,
                result: ToolResultSummary {
                    has_error,
                    output_preview: preview.clone(),
                },
            }],
            created_at,
        });
        let mut effects = vec![AgentEffect::Emit {
            event: AgentEvent::ToolCallCompleted {
                call_id,
                result: ToolResultSummary {
                    has_error,
                    output_preview: preview,
                },
            },
        }];
        if self.state.pending_tools.is_empty() {
            if let Some(run_id) = self.state.active_run {
                self.state.status = AgentStatus::WaitingForBackend;
                let request = self.execution_request(run_id);
                effects.push(AgentEffect::ExecuteBackend { request });
            }
        }
        effects
    }

    fn permission_resolved(
        &mut self,
        id: PermissionId,
        decision: PermissionDecision,
    ) -> Vec<AgentEffect> {
        let Some(call_id) = self.state.pending_permissions.remove(&id) else {
            return Vec::new();
        };
        let Some(call) = self
            .state
            .pending_tools
            .get(&call_id)
            .map(|pending| pending.call.clone())
        else {
            return Vec::new();
        };
        match decision {
            PermissionDecision::Approved => {
                self.state.status = AgentStatus::Executing;
                vec![
                    Self::state_changed(AgentStatus::WaitingForPermission, AgentStatus::Executing),
                    AgentEffect::ExecuteTool {
                        request: ToolRequest {
                            call,
                            permission: PermissionMode::Allow,
                        },
                    },
                ]
            }
            PermissionDecision::Denied => self.tool_failed(call_id, ToolError::PermissionDenied),
        }
    }

    fn child_completed(&mut self, agent_id: AgentId, result: AgentResult) -> Vec<AgentEffect> {
        self.state.children.retain(|child| *child != agent_id);
        self.usage
            .add_child_summary(agent_id, Self::bridge_usage_summary(&result.usage));
        let mut effects = vec![AgentEffect::Emit {
            event: AgentEvent::ChildAgentCompleted {
                agent_id,
                outcome: AgentOutcome::Success,
            },
        }];
        if self.state.children.is_empty() && self.state.status == AgentStatus::WaitingForChildren {
            self.state.status = AgentStatus::Idle;
            effects.push(AgentEffect::Emit {
                event: AgentEvent::StateChanged {
                    from: AgentStatus::WaitingForChildren,
                    to: AgentStatus::Idle,
                },
            });
        }
        effects
    }

    fn child_failed(&mut self, agent_id: AgentId, error: AgentError) -> Vec<AgentEffect> {
        self.state.children.retain(|child| *child != agent_id);
        self.state.last_error = Some(error);
        let mut effects = vec![AgentEffect::Emit {
            event: AgentEvent::ChildAgentCompleted {
                agent_id,
                outcome: AgentOutcome::Failed,
            },
        }];
        if self.state.children.is_empty() && self.state.status == AgentStatus::WaitingForChildren {
            self.state.status = AgentStatus::Idle;
            effects.push(AgentEffect::Emit {
                event: AgentEvent::StateChanged {
                    from: AgentStatus::WaitingForChildren,
                    to: AgentStatus::Idle,
                },
            });
        }
        effects
    }

    /// Converts a protocol usage summary into a core usage summary. The
    /// protocol metrics only carry aggregate token counts, so those are mapped
    /// onto the core `ModelUsage.total_tokens` while the per-kind counters stay
    /// unknown (the same distinction the protocol itself preserves).
    fn bridge_usage_summary(
        protocol: &harness_protocol::usage::AgentUsageSummary,
    ) -> crate::usage::AgentUsageSummary {
        fn to_model_usage(
            metrics: &harness_protocol::usage::AgentUsageMetrics,
        ) -> harness_protocol::usage::ModelUsage {
            harness_protocol::usage::ModelUsage {
                total_tokens: metrics.total_tokens,
                ..Default::default()
            }
        }
        crate::usage::AgentUsageSummary {
            self_usage: to_model_usage(&protocol.self_usage),
            descendant_usage: to_model_usage(&protocol.descendant_usage),
            inclusive_usage: to_model_usage(&protocol.inclusive_usage),
        }
    }

    fn cancel(&mut self) -> Vec<AgentEffect> {
        let from = self.state.status;
        let mut effects = Vec::new();
        if let Some(run_id) = self.state.active_run {
            effects.push(AgentEffect::CancelBackend { run_id });
        }
        let mut calls: Vec<_> = self.state.pending_tools.keys().copied().collect();
        calls.sort();
        effects.extend(calls.into_iter().map(|call_id| AgentEffect::CancelTool { call_id }));
        let mut children = self.state.children.clone();
        children.sort();
        effects.extend(children.into_iter().map(|agent_id| AgentEffect::CancelChild { agent_id }));
        self.state.status = AgentStatus::Cancelled;
        self.state.active_run = None;
        self.state.pending_tools.clear();
        self.state.pending_permissions.clear();
        effects.push(Self::state_changed(from, AgentStatus::Cancelled));
        effects.push(AgentEffect::Emit {
            event: AgentEvent::Completed {
                outcome: AgentOutcome::Cancelled,
            },
        });
        effects
    }

    fn pause(&mut self) -> Vec<AgentEffect> {
        if matches!(
            self.state.status,
            AgentStatus::Cancelled | AgentStatus::Completed | AgentStatus::Failed
        ) {
            return Vec::new();
        }
        let from = self.state.status;
        self.state.status = AgentStatus::Paused;
        vec![Self::state_changed(from, AgentStatus::Paused)]
    }

    fn resume(&mut self) -> Vec<AgentEffect> {
        if self.state.status != AgentStatus::Paused {
            return Vec::new();
        }
        if let Some(run_id) = self.state.active_run {
            self.state.status = AgentStatus::WaitingForBackend;
            let request = self.execution_request(run_id);
            vec![
                Self::state_changed(AgentStatus::Paused, AgentStatus::WaitingForBackend),
                AgentEffect::ExecuteBackend { request },
            ]
        } else {
            self.state.status = AgentStatus::Idle;
            vec![Self::state_changed(AgentStatus::Paused, AgentStatus::Idle)]
        }
    }

    fn assistant_message_id(&mut self) -> MessageId {
        if let Some(message) = self
            .state
            .messages
            .iter()
            .rev()
            .find(|message| message.role == MessageRole::Assistant)
        {
            return message.id;
        }
        let id = self.next_message_id();
        let created_at = self.next_timestamp();
        self.state.messages.push(AgentMessage {
            id,
            role: MessageRole::Assistant,
            content: Vec::new(),
            created_at,
        });
        id
    }

    fn append_assistant_text(&mut self, delta: &str) -> MessageId {
        let id = self.assistant_message_id();
        let message = self
            .state
            .messages
            .iter_mut()
            .find(|message| message.id == id)
            .expect("assistant message exists");
        match message.content.last_mut() {
            Some(ContentBlock::Text { text }) => text.push_str(delta),
            _ => message.content.push(ContentBlock::Text {
                text: delta.to_owned(),
            }),
        }
        id
    }
}

#[cfg(test)]
mod tests {
    use std::collections::HashMap;

    use harness_protocol::backend::{
        BackendBinding, BackendCapabilities, BackendDescriptor, BackendReference,
    };
    use harness_protocol::commands::{AgentCommand, AgentResult, AgentStatus};
    use harness_protocol::effects::AgentEffect;
    use harness_protocol::events::AgentEvent;
    use harness_protocol::ids::{
        AgentId, BackendId, ConfigurationId, IntegrationId, SessionId,
    };
    use harness_protocol::tools::AgentToolset;
    use harness_protocol::usage::{AgentBudget, AgentUsageMetrics, AgentUsageSummary, UsageValue};

    use crate::agent::Agent;
    use crate::capabilities::{AgentCapabilities, WorkspaceCapabilities};

    fn test_agent() -> Agent {
        Agent::new(
            AgentId::new(),
            SessionId::new(),
            None,
            "system".into(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: "fake".into(),
                    description: "fake".into(),
                    capabilities: BackendCapabilities::default(),
                },
            },
            AgentCapabilities {
                tools: AgentToolset {
                    tools: HashMap::new(),
                },
                can_spawn_agents: false,
                max_child_depth: None,
                workspace: WorkspaceCapabilities {
                    can_read: false,
                    can_write: false,
                    can_search: false,
                },
                backend: BackendCapabilities::default(),
            },
            AgentBudget::default(),
        )
    }

    #[test]
    fn child_completed_rolls_up_usage_and_resumes_from_waiting_for_children() {
        let mut agent = test_agent();
        let child_a = AgentId::new();
        let child_b = AgentId::new();
        agent.state.children = vec![child_a, child_b];
        agent.state.status = AgentStatus::WaitingForChildren;

        let usage_a = AgentUsageSummary {
            inclusive_usage: AgentUsageMetrics {
                total_tokens: UsageValue::new(Some(100)),
                ..Default::default()
            },
            ..Default::default()
        };
        let usage_b = AgentUsageSummary {
            inclusive_usage: AgentUsageMetrics {
                total_tokens: UsageValue::new(Some(50)),
                ..Default::default()
            },
            ..Default::default()
        };

        // First child completes: the agent stays WaitingForChildren.
        let effects = agent.apply(AgentCommand::ChildCompleted {
            agent_id: child_a,
            result: AgentResult {
                summary: "a".into(),
                usage: usage_a.clone(),
            },
        });
        assert_eq!(agent.state.status, AgentStatus::WaitingForChildren);
        assert_eq!(agent.state.children, vec![child_b]);
        assert!(
            !effects.iter().any(|e| matches!(
                e,
                AgentEffect::Emit {
                    event: AgentEvent::StateChanged { .. }
                }
            )),
            "no StateChanged should be emitted before all children finish"
        );

        // Second child completes: the agent transitions to Idle and emits StateChanged.
        let effects = agent.apply(AgentCommand::ChildCompleted {
            agent_id: child_b,
            result: AgentResult {
                summary: "b".into(),
                usage: usage_b.clone(),
            },
        });
        assert_eq!(agent.state.status, AgentStatus::Idle);
        assert!(agent.state.children.is_empty());
        assert!(
            effects.iter().any(|e| matches!(
                e,
                AgentEffect::Emit {
                    event: AgentEvent::StateChanged {
                        from: AgentStatus::WaitingForChildren,
                        to: AgentStatus::Idle
                    }
                }
            )),
            "expected StateChanged from WaitingForChildren to Idle"
        );

        // Both children's usage is stored in the ledger for later retrieval.
        let stored_a = agent
            .usage
            .child_usage
            .get(&child_a)
            .expect("child a usage stored");
        assert_eq!(stored_a.inclusive_usage.total_tokens.value(), Some(100));
        let stored_b = agent
            .usage
            .child_usage
            .get(&child_b)
            .expect("child b usage stored");
        assert_eq!(stored_b.inclusive_usage.total_tokens.value(), Some(50));
    }
}

//! Hierarchical supervision and child-agent spawning for one session.

use std::collections::HashMap;
use std::sync::Arc;

use harness_core::agent::Agent;
use harness_core::budget::{BudgetCheck, BudgetError};
use harness_core::capabilities::{AgentCapabilities, CapabilityError};
use harness_protocol::backend::{BackendBinding, BackendDescriptor, BackendReference};
use harness_protocol::commands::{AgentCommand, AgentResult};
use harness_protocol::effects::{BackendPolicy, SpawnAgentSpec, SpawnMode, WorkspacePolicy};
use harness_protocol::ids::{AgentId, BackendId, SessionId};
use harness_protocol::usage::AgentBudget;
use harness_workspace::{ReadOnlyWorkspace, SnapshotWorkspace, WorktreeWorkspace, WorkspaceError};
use serde_json::Value;
use tokio::sync::{mpsc, oneshot, RwLock};
use tokio::task::JoinHandle;
use tokio_util::sync::CancellationToken;

use crate::agent_runner::{AgentRunner, AgentTask};
use crate::cancellation::SessionCancellation;
use crate::integration::{IntegrationError, IntegrationRegistry};
use crate::scheduler::Scheduler;
use crate::session_runtime::LiveStateTable;
use crate::traits::{EventSink, ExecutionBackend, ToolRegistry, Workspace};

struct AgentHandle {
    parent_id: Option<AgentId>,
    depth: u32,
    cancel: CancellationToken,
    join: JoinHandle<()>,
    commands: mpsc::Sender<AgentCommand>,
    result: oneshot::Receiver<AgentResult>,
}

/// The result of spawning according to SpawnMode.
#[derive(Debug, Clone)]
pub enum SpawnOutcome {
    Awaited(AgentResult),
    Detached(AgentId),
}

#[derive(Debug, thiserror::Error)]
pub enum SupervisorError {
    #[error("budget: {0}")]
    Budget(#[from] BudgetError),
    #[error("capability: {0}")]
    Capability(#[from] CapabilityError),
    #[error("integration: {0}")]
    Integration(#[from] IntegrationError),
    #[error("workspace: {0}")]
    Workspace(#[from] WorkspaceError),
    #[error("parent agent not found: {0:?}")]
    ParentNotFound(AgentId),
    #[error("child {0:?} finished without producing a result")]
    ChildResultLost(AgentId),
}

pub struct AgentSupervisor {
    session_id: SessionId,
    session_cancel: SessionCancellation,
    agents: Arc<RwLock<HashMap<AgentId, AgentHandle>>>,
    children_of: Arc<RwLock<HashMap<AgentId, Vec<AgentId>>>>,
    child_capabilities: RwLock<HashMap<AgentId, AgentCapabilities>>,
    child_workspaces: RwLock<HashMap<AgentId, Arc<dyn Workspace>>>,
}

impl AgentSupervisor {
    pub fn new(session_id: SessionId, session_cancel: SessionCancellation) -> Self {
        Self {
            session_id,
            session_cancel,
            agents: Arc::new(RwLock::new(HashMap::new())),
            children_of: Arc::new(RwLock::new(HashMap::new())),
            child_capabilities: RwLock::new(HashMap::new()),
            child_workspaces: RwLock::new(HashMap::new()),
        }
    }

    /// Performs the budget checks before creating a child task.
    pub async fn max_children_depth_check(
        &self,
        parent_id: AgentId,
        parent_depth: u32,
        parent_budget: &AgentBudget,
    ) -> Result<(), SupervisorError> {
        let children = self.children_of.read().await;
        let current = children.get(&parent_id).map_or(0, |ids| ids.len()) as u32;
        parent_budget.check_children(current)?;
        parent_budget.check_depth(parent_depth)?;
        Ok(())
    }

    /// Executes the complete eight-step child spawn flow.
    #[allow(clippy::too_many_arguments)]
    pub async fn spawn_child(
        &self,
        parent: &Agent,
        parent_backend: Arc<dyn ExecutionBackend>,
        integration_registry: &IntegrationRegistry,
        tool_registry: Arc<dyn ToolRegistry>,
        workspace: Arc<dyn Workspace>,
        event_sink: Arc<dyn EventSink>,
        scheduler: Arc<Scheduler>,
        parent_commands_tx: mpsc::Sender<AgentCommand>,
        spec: SpawnAgentSpec,
    ) -> Result<AgentId, SupervisorError> {
        // 1. Gate before creating a child task.
        let parent_depth = 0;
        self.max_children_depth_check(parent.id, parent_depth, &parent.budget)
            .await?;

        // 2. Inherit the parent backend or instantiate a fresh explicit one.
        let (backend, child_backend_reference) = match &spec.backend {
            BackendPolicy::Inherit => (parent_backend, parent.backend.reference.clone()),
            BackendPolicy::Explicit(reference) => {
                let backend = integration_registry
                    .create(
                        &reference.integration.to_string(),
                        reference_to_config(reference),
                    )
                    .await?;
                (backend, reference.clone())
            }
        };

        // 3. Derive capabilities with non-escalating tool/spawn/depth rules.
        let capabilities = parent
            .capabilities
            .derive_child_agent_capabilities(&spec.tools, None, None)?;

        // 4. Resolve the requested workspace policy.
        let child_id = AgentId::new();
        let child_workspace: Arc<dyn Workspace> = match &spec.workspace {
            WorkspacePolicy::Inherit => workspace.clone(),
            WorkspacePolicy::ReadOnly => Arc::new(ReadOnlyWorkspace::new(workspace.clone())),
            WorkspacePolicy::Snapshot => Arc::new(
                SnapshotWorkspace::create(workspace.root())
                    .await
                    .map_err(SupervisorError::from)?,
            ),
            WorkspacePolicy::NewWorktree => Arc::new(
                WorktreeWorkspace::create(workspace.root(), &child_id.to_string())
                    .await
                    .map_err(SupervisorError::from)?,
            ),
        };

        // 5. Preserve the requested child budget.
        // 6. Derive cancellation from the session root.
        let child_cancel = self.session_cancel.child_token();

        // 7. Construct the child and its runner.
        let child_agent = Agent::new(
            child_id,
            parent.session_id,
            Some(parent.id),
            spec.role.clone().unwrap_or_default(),
            BackendBinding {
                reference: child_backend_reference,
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: backend.descriptor().name,
                    description: backend.descriptor().description,
                    capabilities: backend.capabilities(),
                },
            },
            capabilities.clone(),
            spec.budget.clone(),
        );

        let (task, commands_tx) = AgentTask::new(child_id);
        let (result_tx, result_rx) = oneshot::channel::<AgentResult>();
        let mut runner = AgentRunner::new(
            child_agent,
            task,
            backend,
            tool_registry,
            child_workspace.clone(),
            event_sink,
            child_cancel.clone(),
            LiveStateTable::default(),
            scheduler,
        );

        // 8. Run independently, deliver the real terminal command, and clean
        // up concurrent children. AwaitResult is removed by await_child after
        // its result receiver is consumed.
        let agents = Arc::clone(&self.agents);
        let children_of = Arc::clone(&self.children_of);
        let deregister_on_completion = matches!(spec.mode, SpawnMode::Concurrent);
        let join = tokio::spawn(async move {
            runner.run().await;

            let outcome = runner.take_final_result();
            let (command, result) = match outcome {
                Some(Ok(result)) => (
                    AgentCommand::ChildCompleted {
                        agent_id: child_id,
                        result: result.clone(),
                    },
                    result,
                ),
                Some(Err(error)) => (
                    AgentCommand::ChildFailed {
                        agent_id: child_id,
                        error,
                    },
                    AgentResult {
                        summary: format!("child {child_id:?} failed"),
                        usage: Default::default(),
                    },
                ),
                None => {
                    let result = AgentResult {
                        summary: format!(
                            "child {child_id:?} finished with status {:?}",
                            runner.agent.state.status
                        ),
                        usage: Default::default(),
                    };
                    (
                        AgentCommand::ChildCompleted {
                            agent_id: child_id,
                            result: result.clone(),
                        },
                        result,
                    )
                }
            };

            let _ = parent_commands_tx.send(command).await;
            let _ = result_tx.send(result);
            if deregister_on_completion {
                AgentSupervisor::deregister_shared(&agents, &children_of, child_id).await;
            }
        });

        self.register(
            Some(parent.id),
            child_id,
            parent_depth + 1,
            child_cancel,
            join,
            commands_tx,
            result_rx,
        )
        .await;

        self.child_capabilities
            .write()
            .await
            .insert(child_id, capabilities);
        self.child_workspaces
            .write()
            .await
            .insert(child_id, child_workspace);

        Ok(child_id)
    }

    /// Dispatches SpawnMode::Concurrent versus SpawnMode::AwaitResult.
    #[allow(clippy::too_many_arguments)]
    pub async fn spawn_and_drive(
        &self,
        parent: &Agent,
        parent_backend: Arc<dyn ExecutionBackend>,
        integration_registry: &IntegrationRegistry,
        tool_registry: Arc<dyn ToolRegistry>,
        workspace: Arc<dyn Workspace>,
        event_sink: Arc<dyn EventSink>,
        scheduler: Arc<Scheduler>,
        parent_commands_tx: mpsc::Sender<AgentCommand>,
        spec: SpawnAgentSpec,
    ) -> Result<SpawnOutcome, SupervisorError> {
        let mode = spec.mode;
        let child_id = self
            .spawn_child(
                parent,
                parent_backend,
                integration_registry,
                tool_registry,
                workspace,
                event_sink,
                scheduler,
                parent_commands_tx,
                spec,
            )
            .await?;

        match mode {
            SpawnMode::Concurrent => Ok(SpawnOutcome::Detached(child_id)),
            SpawnMode::AwaitResult => {
                Ok(SpawnOutcome::Awaited(self.await_child(child_id).await?))
            }
        }
    }

    pub async fn await_child(&self, child_id: AgentId) -> Result<AgentResult, SupervisorError> {
        let handle = {
            let mut agents = self.agents.write().await;
            agents
                .remove(&child_id)
                .ok_or(SupervisorError::ChildResultLost(child_id))?
        };

        if let Some(parent_id) = handle.parent_id {
            let mut children = self.children_of.write().await;
            if let Some(ids) = children.get_mut(&parent_id) {
                ids.retain(|id| *id != child_id);
            }
        }

        let _ = handle.join.await;
        handle
            .result
            .await
            .map_err(|_| SupervisorError::ChildResultLost(child_id))
    }

    pub async fn child_capabilities(&self, child_id: AgentId) -> Option<AgentCapabilities> {
        self.child_capabilities.read().await.get(&child_id).cloned()
    }

    pub async fn child_workspace(&self, child_id: AgentId) -> Option<Arc<dyn Workspace>> {
        self.child_workspaces.read().await.get(&child_id).cloned()
    }

    pub async fn child_commands(&self, child_id: AgentId) -> Option<mpsc::Sender<AgentCommand>> {
        self.agents
            .read()
            .await
            .get(&child_id)
            .map(|handle| handle.commands.clone())
    }

    /// Purely computes self, descendant, and inclusive usage.
    pub fn inclusive_usage(
        &self,
        agent: &Agent,
    ) -> harness_core::usage::AgentUsageSummary {
        let records = agent.usage.records.clone();
        let children = agent.usage.child_usage.values().cloned().collect();
        harness_core::usage::compute_agent_usage_summary(&records, &children)
    }

    async fn register(
        &self,
        parent_id: Option<AgentId>,
        child_id: AgentId,
        depth: u32,
        cancel: CancellationToken,
        join: JoinHandle<()>,
        commands: mpsc::Sender<AgentCommand>,
        result: oneshot::Receiver<AgentResult>,
    ) {
        let mut agents = self.agents.write().await;
        let mut children = self.children_of.write().await;
        agents.insert(
            child_id,
            AgentHandle {
                parent_id,
                depth,
                cancel,
                join,
                commands,
                result,
            },
        );
        if let Some(parent_id) = parent_id {
            children.entry(parent_id).or_default().push(child_id);
        }
    }

    async fn deregister_shared(
        agents: &RwLock<HashMap<AgentId, AgentHandle>>,
        children_of: &RwLock<HashMap<AgentId, Vec<AgentId>>>,
        child_id: AgentId,
    ) {
        let mut agents = agents.write().await;
        if let Some(handle) = agents.remove(&child_id) {
            if let Some(parent_id) = handle.parent_id {
                let mut children = children_of.write().await;
                if let Some(ids) = children.get_mut(&parent_id) {
                    ids.retain(|id| *id != child_id);
                }
            }
        }
    }

    async fn deregister(&self, child_id: AgentId) {
        Self::deregister_shared(&self.agents, &self.children_of, child_id).await;
    }
}

fn reference_to_config(reference: &BackendReference) -> Value {
    serde_json::to_value(reference).unwrap_or_else(|_| serde_json::json!({}))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    use harness_core::capabilities::WorkspaceCapabilities;
    use harness_protocol::backend::{BackendCapabilities, BackendDescriptor, BackendReference};
    use harness_protocol::events::AgentEventEnvelope;
    use harness_protocol::ids::{ConfigurationId, IntegrationId};
    use harness_protocol::tools::AgentToolset;

    use crate::scheduler::SchedulerConfig;
    use crate::testing::{FakeBackend, FakeToolRegistry};
    use crate::traits::EventSink;
    use crate::workspace::FakeWorkspace;

    struct NoopSink;
    impl EventSink for NoopSink {
        fn send(&self, _: AgentEventEnvelope) {}
    }

    fn parent(session_id: SessionId) -> Agent {
        Agent::new(
            AgentId::new(),
            session_id,
            None,
            "parent".into(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: "fake".into(),
                    description: "fake".into(),
                    capabilities: BackendCapabilities::default(),
                },
            },
            AgentCapabilities {
                tools: AgentToolset {
                    tools: HashMap::new(),
                },
                can_spawn_agents: true,
                max_child_depth: Some(5),
                workspace: WorkspaceCapabilities {
                    can_read: true,
                    can_write: true,
                    can_search: true,
                },
                backend: BackendCapabilities::default(),
            },
            AgentBudget::default(),
        )
    }

    #[tokio::test]
    async fn max_children_gate_rejects_third_child() {
        let supervisor = AgentSupervisor::new(SessionId::new(), SessionCancellation::new());
        let parent_id = AgentId::new();
        let budget = AgentBudget {
            max_children: Some(2),
            ..Default::default()
        };

        for _ in 0..2 {
            let child_id = AgentId::new();
            let cancel = supervisor.session_cancel.child_token();
            let join = tokio::spawn(async {});
            let (commands, _) = mpsc::channel(1);
            let (_, result) = oneshot::channel();
            supervisor
                .register(Some(parent_id), child_id, 1, cancel, join, commands, result)
                .await;
        }

        let error = supervisor
            .max_children_depth_check(parent_id, 0, &budget)
            .await
            .expect_err("third child must be rejected");
        assert!(matches!(
            error,
            SupervisorError::Budget(BudgetError::TooManyChildren { .. })
        ));
    }

    #[test]
    fn inclusive_usage_is_a_pure_aggregate() {
        let session = SessionId::new();
        let supervisor = AgentSupervisor::new(session, SessionCancellation::new());
        let root = parent(session);
        let before = root.usage.records.len();
        let summary = supervisor.inclusive_usage(&root);
        assert_eq!(summary.self_usage.total_tokens.value(), None);
        assert_eq!(root.usage.records.len(), before);
    }

    #[allow(dead_code)]
    fn _spawn_dependencies() {
        let _ = (
            Scheduler::new(SchedulerConfig::default()),
            FakeBackend::new(),
            FakeToolRegistry::new(),
            FakeWorkspace::new(),
        );
    }
